public int findLargestSubstring(List<String> strings) {
    // Initialize a map to store the length of each distinct substring
    Map<String, Integer> substringLengths = new HashMap<>();

    // Loop through each string in the list
    for (String string : strings) {
        // Loop through each substring of the current string
        for (int i = 0; i < string.length(); i++) {
            // Check if the substring is a palindrome and if it's the longest so far
            if (isPalindrome(string.substring(i)) && (substringLengths.get(string.substring(i)) == null || substringLengths.get(string.substring(i)) < string.substring(i).length())) {
                substringLengths.put(string.substring(i), string.substring(i).length());
            }
        }
    }

    // Return the length of the longest palindromic substring
    return substringLengths.values().stream().max(Integer::compare).orElse(0);
}

