    Set<String> inverses = new HashSet<>();

    // Iterate over each string in the list
    for (String string : strings) {
        // If the string is not already in the set, add its inverse to the set
        if (!strings.contains(string)) {
            inverses.add(new StringBuilder(string).reverse().toString());
        }
    }

    // Initialize the largest substring length
