    // Iterate over each inverse string in the set
    for (String inverse : inverses) {
        // Find the longest common substring between the original string and its inverse
        String longestCommonSubstring = findLongestCommonSubstring(strings, inverse);
        // Update the largest substring length if necessary
        largestSubstringLength = Math.max(largestSubstringLength, longestCommonSubstring.length());
    }

    return largestSubstringLength;
}

