public boolean canArrange(int[] arr, int k) {
    // Check if the divisor is valid
    if (k > 0 && k <= 31) {
        return true;
    }

    // Create a dictionary to store the pairs
    Map<Integer, Integer> pairs = new HashMap<>();

    // Iterate over the array and create the pairs
    for (int num : arr) {
        int pair = num / k;
        int remainder = num % k;

        // Check if the remainder is zero
        if (remainder == 0) {
            pairs.put(pair, num);
        } else {
            // Check if the pair already exists
            if (pairs.containsKey(pair)) {
                int existingNum = pairs.get(pair);

                // Check if the sum of the pair is divisible by the divisor
                if ((existingNum + num) % k == 0) {
                    pairs.put(pair, num);
                }
            } else {
                pairs.put(pair, num);
            }
        }
    }

    // Check if all the pairs have been divided evenly
    for (Map.Entry<Integer, Integer> entry : pairs.entrySet()) {
        int pair = entry.getKey();
        int num = entry.getValue();

        // Check if the sum of the pair is divisible by the divisor
        if ((pair + num) % k != 0) {
            return false;
        }
    }

    return true;
}

