public boolean canArrange(int[] arr, int k) {
  if (k <= 1 || arr.length <= 2) {
    // base case
    return arr.length == 2;
  }
  int n = arr.length;
  // determine if there exist two elements with the same remainder when divided by k
  for (int i = 0; i < n - 1; i++) {
    for (int j = i + 1; j < n; j++) {
      if (arr[i] % k == arr[j] % k) {
        return false;
      }
    }
  }
  // determine if there exists an element that is divisible by k
  for (int i = 0; i < n; i++) {
    if (arr[i] % k == 0) {
      return false;
    }
  }
  // it is possible to divide the array into n/2 pairs
  return true;
}

