public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Initialize the minTime to 0
    int minTime = 0;

    // Create a graph to represent the tree
    Graph graph = new Graph(n);
    for (int i = 0; i < edges.length; i++) {
        graph.addEdge(edges[i][0], edges[i][1], 1);
    }

    // Perform a depth-first search from node 0
    Node node = graph.getNode(0);
    Set<Node> visited = new HashSet<>();
    Deque<Node> stack = new ArrayDeque<>();
    stack.push(node);
    while (!stack.isEmpty()) {
        node = stack.pop();
        if (!visited.contains(node)) {
            visited.add(node);
            // If the current node has an apple, add the time required to collect it
            if (hasApple[node.id]) {
                minTime += 2;
            }
            // Add the time required to move from the current node to its neighbors
            for (Node neighbor : graph.getNeighbors(node)) {
                if (!visited.contains(neighbor)) {
                    stack.push(neighbor);
                }
            }
        }
    }

    return minTime;
}

