public static int squarePermutations(int[] A) {
    // Initialize a set to store the unique permutations
    Set<List<Integer>> permutations = new HashSet<>();
    // Get the sum of each pair of adjacent elements in the array
    for (int i = 0; i < A.length - 1; i++) {
        int sum = A[i] + A[i + 1];
        // Check if the sum is a perfect square
        if (isPerfectSquare(sum)) {
            // If it is a perfect square, add the permutation to the set
            permutations.add(Arrays.asList(A[i], A[i + 1]));
            // Swap the elements to check for other permutations
            int temp = A[i];
            A[i] = A[i + 1];
            A[i + 1] = temp;
        }
    }
    // Return the number of unique permutations
    return permutations.size();
}

