  int firstUnsortedIndex = 0;
  while (firstUnsortedIndex < sortedDigits.length - 1 && sortedDigits[firstUnsortedIndex] == sortedDigits[firstUnsortedIndex + 1]) {
    firstUnsortedIndex++;
