public static int minPerfectSquareSum(int n) {
    // Initialize a list to store the perfect square numbers
    List<Integer> perfectSquares = new ArrayList<>();

    // Iterate from 1 to the square root of n
    for (int i = 1; i * i <= n; i++) {
        // If i is a perfect square, add it to the list
        if (i * i == n) {
            perfectSquares.add(i);
        }
    }

    // Initialize the minimum number of perfect square numbers to 0
    int minPerfectSquares = 0;

    // Iterate through the list of perfect square numbers
    for (int perfectSquare : perfectSquares) {
        // If the current perfect square number is a factor of n, increment the minimum number of perfect square numbers
        if (n % perfectSquare == 0) {
            minPerfectSquares++;
        }
    }

    // Return the minimum number of perfect square numbers
    return minPerfectSquares;
}

